    tagline: '社会保険は社会保険審査官→審査会の二審、保険料は審査会に直接で一審。労働保険は労働保険審査官→審査会。却下みなしは社保2か月・労保3か月。',
    subjects: ['konen', 'kenpo', 'koyo', 'rosai', 'kokunen'],
